local MetalMeshMaker = {}
local PRODUCTS = {
    simple_iron_mesh = { name = "Preprosta železna mreža", ironCost = 3, time = 4, cost = 80, defense = 8, happiness = 1, description = "Preprosta železna mreža za zaščito." },
    brass_woven_mesh = { name = "Medeninastovpeta mreža", brassCost = 2, ironCost = 2, time = 6, cost = 220, defense = 14, happiness = 1, prestige = 2, description = "Medeninastovpeta mreža za trgovce." },
    silver_wire_mesh = { name = "Srebrnatična mreža", silverCost = 2, brassCost = 1, ironCost = 2, time = 9, cost = 540, defense = 22, happiness = 2, prestige = 6, description = "Srebrnatična mreža za plemiče." },
    gold_trimmed_mesh = { name = "Zlatookrasna mreža", goldCost = 1, silverCost = 1, brassCost = 1, ironCost = 2, time = 13, cost = 1300, defense = 30, happiness = 3, prestige = 14, description = "Zlatookrasna mreža za visoke plemiče." },
    jewel_set_mesh = { name = "Draguljasta mreža", goldCost = 1, silverCost = 1, brassCost = 1, ironCost = 2, jewelCost = 1, time = 17, cost = 2900, defense = 40, happiness = 5, prestige = 27, description = "Mreža z draguljem za visoko plemstvo." },
    royal_grand_mesh = { name = "Kraljevski veliki mreža", goldCost = 2, silverCost = 2, brassCost = 1, ironCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 6200, defense = 52, happiness = 12, prestige = 58, description = "Velika kraljevska mreža z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    mesh_workshop = { name = "Mrežna delavnica", cost = { gold = 260, wood = 120, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    weaving_loft = { name = "Pletilska podstrešje", cost = { gold = 950, wood = 280, stone = 240, silver = 6, brass = 6 }, upkeep = 22, qualityBonus = 18 },
    master_mesh_atelier = { name = "Mojstrski mrežni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_mesh_palace = { name = "Kraljevska mrežna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
MetalMeshMaker.ironStock = 16; MetalMeshMaker.brassStock = 12; MetalMeshMaker.silverStock = 8; MetalMeshMaker.goldStock = 6; MetalMeshMaker.jewelStock = 4; MetalMeshMaker.pearlStock = 4
MetalMeshMaker.productStock = {}; MetalMeshMaker.buildings = {}; MetalMeshMaker.maker = nil; MetalMeshMaker.activeMaking = {}; MetalMeshMaker.totalProducts = 0; MetalMeshMaker.dayTimer = 0
function MetalMeshMaker.init() MetalMeshMaker.ironStock=16; MetalMeshMaker.brassStock=12; MetalMeshMaker.silverStock=8; MetalMeshMaker.goldStock=6; MetalMeshMaker.jewelStock=4; MetalMeshMaker.pearlStock=4; MetalMeshMaker.productStock={}; MetalMeshMaker.buildings={}; MetalMeshMaker.maker=nil; MetalMeshMaker.activeMaking={}; MetalMeshMaker.totalProducts=0; MetalMeshMaker.dayTimer=0; print("[MetalMeshMaker] Royal Metal Mesh Maker System initialized (6 products, 4 buildings)") end
function MetalMeshMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MetalMeshMaker.maker={name=n or ("Mrežar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mrežar najet: %s (spretnost: %d)",MetalMeshMaker.maker.name,s),"success") end; return true end
function MetalMeshMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MetalMeshMaker.build(id) local ok,e=MetalMeshMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MetalMeshMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MetalMeshMaker.getQualityBonus() local b=0; for _,bd in ipairs(MetalMeshMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MetalMeshMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MetalMeshMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.brassCost and MetalMeshMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and MetalMeshMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MetalMeshMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MetalMeshMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MetalMeshMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MetalMeshMaker.buildings==0 then return false,"Potrebna mrežna delavnica" end; if not MetalMeshMaker.maker then return false,"Potreben mrežar" end; return true end
function MetalMeshMaker.make(pt,qty) qty=qty or 1; local ok,e=MetalMeshMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MetalMeshMaker.ironStock=MetalMeshMaker.ironStock-d.ironCost*qty end; if d.brassCost then MetalMeshMaker.brassStock=MetalMeshMaker.brassStock-d.brassCost*qty end; if d.silverCost then MetalMeshMaker.silverStock=MetalMeshMaker.silverStock-d.silverCost*qty end; if d.goldCost then MetalMeshMaker.goldStock=MetalMeshMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MetalMeshMaker.jewelStock=MetalMeshMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MetalMeshMaker.pearlStock=MetalMeshMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MetalMeshMaker.maker then t=math.max(1,t-math.floor(MetalMeshMaker.maker.skill/13)) end; table.insert(MetalMeshMaker.activeMaking,{id="metalmesh_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MetalMeshMaker.completeMaking(m) local q=1.0+(MetalMeshMaker.getQualityBonus()/100); if MetalMeshMaker.maker then q=q+(MetalMeshMaker.maker.skill/140) end; q=math.min(2.5,q); MetalMeshMaker.productStock[m.productType]=(MetalMeshMaker.productStock[m.productType] or 0)+m.quantity; MetalMeshMaker.totalProducts=MetalMeshMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MetalMeshMaker.maker then MetalMeshMaker.maker.itemsMade=MetalMeshMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MetalMeshMaker.maker.skill=math.min(100,MetalMeshMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mreža izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"metalmesh.completed",{productName=m.productName,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function MetalMeshMaker.update(dt) if not _G.state then return end; MetalMeshMaker.dayTimer=MetalMeshMaker.dayTimer+dt; if MetalMeshMaker.dayTimer>=30 then MetalMeshMaker.dayTimer=0; for i=#MetalMeshMaker.activeMaking,1,-1 do local m=MetalMeshMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MetalMeshMaker.completeMaking(m); table.remove(MetalMeshMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MetalMeshMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MetalMeshMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MetalMeshMaker.getStats() return {ironStock=MetalMeshMaker.ironStock,brassStock=MetalMeshMaker.brassStock,silverStock=MetalMeshMaker.silverStock,goldStock=MetalMeshMaker.goldStock,jewelStock=MetalMeshMaker.jewelStock,pearlStock=MetalMeshMaker.pearlStock,productStock=MetalMeshMaker.productStock,numBuildings=#MetalMeshMaker.buildings,hasMaker=MetalMeshMaker.maker~=nil,makerName=MetalMeshMaker.maker and MetalMeshMaker.maker.name or "—",makerSkill=MetalMeshMaker.maker and MetalMeshMaker.maker.skill or 0,activeMaking=#MetalMeshMaker.activeMaking,totalProducts=MetalMeshMaker.totalProducts} end
return MetalMeshMaker
